from agent import *from models.products import *import simplejsonXCAT = ['About Us', 'Contact Us', 'Where to Buy']def run(context: dict[str, str], session: Session):    session.queue(Request('https://www.timemore.com/', use='curl', force_charset='utf-8'), process_catlist, {})def process_catlist(data: Response, context: dict[str, str], session: Session):    cats = data.xpath('//li[contains(@class, "site-nav")]/a')    for cat in cats:        name = cat.xpath('text()').string()        url = cat.xpath('@href').string()        if url and name and name not in XCAT:            session.queue(Request(url, use='curl', force_charset='utf-8'), process_prodlist, dict(cat=name))def process_prodlist(data: Response, context: dict[str, str], session: Session):    prods = data.xpath('//div[contains(@class, "grid__item grid-product")]')    for prod in prods:        name = prod.xpath('.//div[contains(@class, "title")]/text()').string()        url = prod.xpath('.//a[@class="grid-product__link"]/@href').string()        rev_cnt = prod.xpath('.//ryviu-widget-total/@reviews_data').string()        if rev_cnt:            rev_cnt = rev_cnt.split(';')[0]            if rev_cnt and int(rev_cnt) > 0:                session.queue(Request(url, use='curl', force_charset='utf-8'), process_product, dict(context, name=name, url=url))def process_product(data: Response, context: dict[str, str], session: Session):    product = Product()    product.name = context['name']    product.url = context['url']    product.category = context['cat']    product.ssid = data.xpath('//div[@class="product-section"]/@data-product-id').string()    product.manufacturer = 'TIMEMORE'    prod_json = data.xpath('//script[@type="application/ld+json"]/text()').string()    if prod_json:        prod_json = simplejson.loads(prod_json)        product.sku = prod_json.get('sku')        ean = prod_json.get('gtin14')        if ean:            product.properties.append(ProductProperty(type='id.ean', value=ean))    if product.ssid:        rev_url = "https://app.ryviu.io/frontend/client/get-more-reviews?domain=timemore-re.myshopify.com"        options = """-H 'authority: app.ryviu.io' -H 'accept: */*' -H 'accept-language: uk,en;q=0.9,en-GB;q=0.8,en-US;q=0.7' -H 'cache-control: no-cache' -H 'referer: https://www.timemore.com/' -H 'user-agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/116.0.0.0 Safari/537.36 Edg/116.0.1938.69' --data-raw '{"product_id":%s,"page":1,"type":"load-more","order":null,"filter":"all","feature":false,"domain":"timemore-re.myshopify.com","platform":"shopify"}' --compressed""" % product.ssid        session.do(Request(rev_url, use='curl', options=options, max_age=0, force_charset='utf-8'), process_reviews, dict(product=product))def process_reviews(data: Response, context: dict[str, str], session: Session):    revs_json = simplejson.loads(data.content)    product = context['product']    revs = revs_json['more_reviews']    for rev in revs:        if rev.get('country_code') != 'us':            continue        review = Review()        review.type = "user"        review.url = product.url        review.date = rev.get('created_at_format')        title = rev.get('title')        if title:            title = title.encode("ascii", errors="ignore").strip()            if title:                review.title = title        author = rev.get('author')        if author:            author = author.encode("ascii", errors="ignore").strip()            if author:                review.authors.append(Person(name=author, ssid=author))        grade_overall = rev.get('rating')        if grade_overall:            review.grades.append(Grade(type="overall", value=float(grade_overall), best=5.0))        hlp_yes = rev.get('like')        if hlp_yes:            review.add_property(type='helpful_votes', value=int(hlp_yes))        hlp_no = rev.get('dislike')        if hlp_no:            review.add_property(type='not_helpful_votes', value=int(hlp_no))        excerpt = rev.get('body_text')        if excerpt:            excerpt = excerpt.encode("ascii", errors="ignore")            if excerpt:                review.properties.append(ReviewProperty(type="excerpt", value=excerpt))                review.ssid = review.digest() if author else review.digest(excerpt)                product.reviews.append(review)    revs_cnt = revs_json.get('total')    offset = context.get('offset', 0) + 10    if revs_cnt and int(revs_cnt) > offset:        next_page = context.get('page', 1) + 1        rev_url = "https://app.ryviu.io/frontend/client/get-more-reviews?domain=timemore-re.myshopify.com"        options = """-H 'authority: app.ryviu.io' -H 'accept: */*' -H 'accept-language: uk,en;q=0.9,en-GB;q=0.8,en-US;q=0.7' -H 'cache-control: no-cache' -H 'referer: https://www.timemore.com/' -H 'user-agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/116.0.0.0 Safari/537.36 Edg/116.0.1938.69' --data-raw '{"handle":"timemore-chestnut-c3-pro-manual-coffee-grinder","product_id":%s,"page":%s,"type":"load-more","order":null,"filter":"all","feature":false,"domain":"timemore-re.myshopify.com","platform":"shopify"}' --compressed""" % (product.ssid, next_page)        session.do(Request(rev_url, use='curl', options=options, max_age=0, force_charset='utf-8'), process_reviews, dict(context, offset=offset, product=product, page=next_page))    elif product.reviews:        session.emit(product)